+  position: absolute;
+  left: 1rem;
+  top: 1rem;
+  z-index: 10;
+  transform: translateY(-150%);
+  border-radius: 999px;
+  padding: 0.7rem 1rem;
+  background: var(--color-text);
+  color: var(--color-surface);
+  font-weight: 700;
+}
+
+.skip-link:focus {
